def _full_window_only(ranks: pd.DataFrame) -> pd.DataFrame:
    """Keep only days where the full 30-day window is available."""
    return ranks[ranks["day"] >= WINDOW].copy()


def test_full_agreement_with_pandas(sql_ranks, pandas_ranks):
    merged = _full_window_only(sql_ranks).merge(
        _full_window_only(pandas_ranks), on=["day", "region"], how="inner"
    )
    # every (day, region) pair present on both sides
    expected_pairs = WINDOW - 1 + len(REGION_BASES) * 0  # placeholder no-op
    n_expected = (500 - WINDOW + 1) * len(REGION_BASES)
    assert len(merged) == n_expected
    assert (merged["rank"] == merged["pandas_rank"]).all()


def test_ranks_are_permutation_of_1_to_4(sql_ranks):
    full = _full_window_only(sql_ranks)
    counts = full.groupby("day")["rank"].apply(lambda s: sorted(s.tolist()))
    assert all(c == [1, 2, 3, 4] for c in counts)
    assert sorted(full["day"].unique().tolist()) == list(range(WINDOW, 501))


def test_base_1200_region_leads_most_days(sql_ranks, data):
    leader_region = max(REGION_BASES, key=REGION_BASES.get)
    assert REGION_BASES[leader_region] == 1200
    full = _full_window_only(sql_ranks)
    top = full[full["rank"] == 1]["region"].value_counts()
    assert top.index[0] == leader_region
    pct = top.iloc[0] / full["day"].nunique()
    assert pct >= 0.90
